import React from 'react';
import {
  render,
  fireEvent,
  screen,
  waitFor,
  within,
} from '@testing-library/react-native';
import SettingsScreen from '../../src/screens/SettingsScreen';
import {
  createStore,
  createMemoryRawStore,
  createMemoryKeyProvider,
} from '../../src/lib/storage/memory';
import * as appLock from '../../src/lib/appLock';
import { theme } from '../../src/theme';

// ---------------------------------------------------------------------------
// Mock navigation -----------------------------------------------------------
// ---------------------------------------------------------------------------
let mockNavigate: jest.Mock;
jest.mock('@react-navigation/native', () => {
  const actual = jest.requireActual('@react-navigation/native');
  mockNavigate = jest.fn();
  return {
    ...actual,
    useNavigation: () => ({
      navigate: mockNavigate,
    }),
  };
});

// ---------------------------------------------------------------------------
// Mock app‑lock helpers ------------------------------------------------------
// ---------------------------------------------------------------------------
jest.mock('../../src/lib/appLock', () => ({
  getAppLockEnabled: jest.fn().mockResolvedValue(false),
  setAppLockEnabled: jest.fn().mockResolvedValue(undefined),
}));

// ---------------------------------------------------------------------------
// Mock settings helpers (used only for UI state) ---------------------------
// ---------------------------------------------------------------------------
jest.mock('../../src/lib/settings', () => ({
  getMileageRate: jest.fn().mockResolvedValue(0.5),
  setMileageRate: jest.fn(),
  getTaxRate: jest.fn().mockResolvedValue(0.2),
  setTaxRate: jest.fn(),
}));

describe('SettingsScreen UI', () => {
  // Helper that renders the screen – SettingsScreen reads the store internally
  // (via its own hook/context). The store does not need to be injected here
  // because the component uses the same in‑memory API that the tests use.
  const renderScreen = () => render(<SettingsScreen />);

  it('renders the App lock row with a switch and no chevron', async () => {
    renderScreen();

    // The row label must appear.
    await waitFor(() => {
      expect(screen.getByText('App lock')).toBeTruthy();
    });

    // The switch should be present (accessibility role = "switch").
    const switchEl = screen.getByA11yRole('switch');
    expect(switchEl).toBeTruthy();

    // The SettingsRow that holds the switch receives a deterministic testID.
    const row = screen.getByTestId('settings-row-app-lock');
    expect(row).toBeTruthy();

    // No chevron icon should be rendered inside this row.
    const chevron = within(row).queryByTestId('chevron-icon');
    expect(chevron).toBeNull();
  });

  it('toggles the App lock switch and calls setAppLockEnabled', async () => {
    renderScreen();

    await waitFor(() => {
      expect(screen.getByA11yRole('switch')).toBeTruthy();
    });

    const switchEl = screen.getByA11yRole('switch');

    // Simulate a toggle to the "on" position.
    fireEvent(switchEl, 'valueChange', true);

    expect(appLock.setAppLockEnabled).toHaveBeenCalledWith(true);
  });

  it('renders navigation rows with chevron icons and navigates correctly', async () => {
    renderScreen();

    const rows = [
      { label: 'Tax settings', target: 'TaxSettingsScreen' },
      { label: 'Categories', target: 'CategoriesScreen' },
      { label: 'Export', target: 'ExportScreen' },
      { label: 'Backup & restore', target: 'BackupScreen' },
      {
        label: 'View Terms and Privacy Policy',
        target: 'PrivacyPolicyScreen',
      },
    ];

    for (const { label, target } of rows) {
      // Each row should be a pressable button with an accessible label.
      const button = await screen.findByRole('button', { name: label });
      expect(button).toBeTruthy();

      // Every navigable row must contain a chevron‑right icon.
      const chevron = within(button).getByTestId('chevron-icon');
      expect(chevron).toBeTruthy();

      // Press the row and verify navigation.
      fireEvent.press(button);
      expect(mockNavigate).toHaveBeenCalledWith(target);
    }
  });

  it('renders Delete all data row with error colour and a separator above it', async () => {
    renderScreen();

    // A separator component should precede the delete row (testID added by the
    // implementation).
    const separator = screen.getByTestId('separator-before-delete');
    expect(separator).toBeTruthy();

    // Delete‑all row – the implementation adds a deterministic testID.
    const deleteRow = screen.getByTestId('settings-row-delete-all-data');
    expect(deleteRow).toBeTruthy();

    // The visible text.
    const deleteText = within(deleteRow).getByText('Delete all data');
    expect(deleteText).toBeTruthy();

    // It must be styled with the error colour from the theme.
    expect(deleteText).toHaveStyle({ color: theme.colors.error });

    // Pressing the row should navigate to the DeleteAllData screen.
    fireEvent.press(deleteRow);
    expect(mockNavigate).toHaveBeenCalledWith('DeleteAllDataScreen');
  });
});
````

