import React from 'react';
import renderer, { act, ReactTestRenderer } from 'react-test-renderer';

// ---------------------------------------------------------------------------
// Mock navigation – capture calls to navigate()
// ---------------------------------------------------------------------------
let mockNavigate: jest.Mock;
jest.mock('@react-navigation/native', () => {
  const actual = jest.requireActual('@react-navigation/native');
  mockNavigate = jest.fn();
  return {
    ...actual,
    useNavigation: () => ({
      navigate: mockNavigate,
    }),
  };
});

// ---------------------------------------------------------------------------
// Mock app‑lock helpers – used by the App‑lock switch row
// ---------------------------------------------------------------------------
jest.mock('../../src/lib/appLock', () => ({
  getAppLockEnabled: jest.fn().mockResolvedValue(false),
  setAppLockEnabled: jest.fn(),
}));

// ---------------------------------------------------------------------------
// Mock settings helpers – the screen reads these but they are not part of the
// UI‑logic we are testing, so we stub them out.
// ---------------------------------------------------------------------------
jest.mock('../../src/lib/settings', () => ({
  getMileageRate: jest.fn().mockResolvedValue(0.5),
  setMileageRate: jest.fn(),
  getTaxRate: jest.fn().mockResolvedValue(0.2),
  setTaxRate: jest.fn(),
}));

// ---------------------------------------------------------------------------
// Import the screen under test and the UI primitives it renders.
// ---------------------------------------------------------------------------
import SettingsScreen from '../../src/screens/SettingsScreen';
import SettingsRow from '../../src/components/ui/SettingsRow';
import Separator from '../../src/components/ui/Separator';
import { theme } from '../../src/theme';

// ---------------------------------------------------------------------------
// Helper: render the screen inside act() so that all useEffect async work
// finishes before we start querying the tree.
// ---------------------------------------------------------------------------
async function renderScreen(): Promise<ReactTestRenderer> {
  let testRenderer: ReactTestRenderer;
  await act(async () => {
    testRenderer = renderer.create(<SettingsScreen />);
  });
  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
  return testRenderer!;
}

describe('SettingsScreen UI logic (acceptance)', () => {
  beforeEach(() => {
    mockNavigate.mockClear();
    // Reset mocked implementations in case a test mutates them
    const { getAppLockEnabled } = require('../../src/lib/appLock');
    getAppLockEnabled.mockResolvedValue(false);
  });

  it('renders an App lock row with a switch and no chevron', async () => {
    const testRenderer = await renderScreen();
    const root = testRenderer.root;

    const appLockRow = root.findByProps({ testID: 'settings-row-app-lock' });
    expect(appLockRow).toBeTruthy();

    // Switch props are passed via the SettingsRow component
    expect(appLockRow.props.showSwitch).toBe(true);
    expect(appLockRow.props.showChevron).toBeFalsy();

    // No chevron element should be rendered – we expose a testID on any chevron.
    const chevron = () => {
      try {
        return root.findByProps({ testID: 'chevron-app-lock' });
      } catch {
        return null;
      }
    };
    expect(chevron()).toBeNull();
  });

  it('toggles the App lock switch and calls setAppLockEnabled', async () => {
    const { setAppLockEnabled } = require('../../src/lib/appLock');
    const testRenderer = await renderScreen();
    const root = testRenderer.root;

    const appLockRow = root.findByProps({ testID: 'settings-row-app-lock' });
    // SettingsRow receives an onSwitchChange prop that the UI component uses.
    expect(typeof appLockRow.props.onSwitchChange).toBe('function');

    // Simulate turning the switch on.
    act(() => {
      appLockRow.props.onSwitchChange(true);
    });
    expect(setAppLockEnabled).toHaveBeenCalledWith(true);

    // Simulate turning the switch off.
    act(() => {
      appLockRow.props.onSwitchChange(false);
    });
    expect(setAppLockEnabled).toHaveBeenCalledWith(false);
  });

  it('renders navigation rows with chevron icons and navigates correctly', async () => {
    const testRenderer = await renderScreen();
    const root = testRenderer.root;

    const rows = [
      { testID: 'settings-row-tax-settings', label: 'Tax settings', target: 'TaxSettingsScreen' },
      { testID: 'settings-row-categories', label: 'Categories', target: 'CategoriesScreen' },
      { testID: 'settings-row-export', label: 'Export', target: 'ExportScreen' },
      { testID: 'settings-row-backup-restore', label: 'Backup & restore', target: 'BackupScreen' },
      {
        testID: 'settings-row-terms',
        label: 'View Terms and Privacy Policy',
        target: 'PrivacyPolicyScreen',
      },
    ];

    for (const { testID, label, target } of rows) {
      const row = root.findByProps({ testID });
      expect(row).toBeTruthy();
      // Row text must match label (the SettingsRow component forwards it via a prop)
      expect(row.props.label).toBe(label);
      // All navigable rows must show a chevron.
      expect(row.props.showChevron).toBe(true);
      // onPress should be defined and call navigate().
      expect(typeof row.props.onPress).toBe('function');

      act(() => {
        row.props.onPress();
      });
      expect(mockNavigate).toHaveBeenCalledWith(target);
      mockNavigate.mockClear();
    }
  });

  it('renders Delete all data row with error colour, separated by a Separator, and navigates', async () => {
    const testRenderer = await renderScreen();
    const root = testRenderer.root;

    // Separator that visually separates the Delete row.
    const separator = root.findByProps({ testID: 'separator-before-delete' });
    expect(separator).toBeTruthy();
    expect(separator.type).toBe(Separator);

    // Delete‑all row.
    const deleteRow = root.findByProps({ testID: 'settings-row-delete-all-data' });
    expect(deleteRow).toBeTruthy();

    // It should display the error colour from the theme.
    // The SettingsRow component passes an `error` prop that is turned into a style
    // using theme.colors.error – we assert the prop is truthy.
    expect(deleteRow.props.error).toBe(true);

    // No chevron is required for the delete row (spec says “styled with error
    // colour, separated from others” – we accept either, but we assert that the
    // implementation does not show a chevron.
    expect(deleteRow.props.showChevron).toBeFalsy();

    // Pressing the row should navigate to the DeleteAllData screen.
    expect(typeof deleteRow.props.onPress).toBe('function');
    act(() => {
      deleteRow.props.onPress();
    });
    expect(mockNavigate).toHaveBeenCalledWith('DeleteAllDataScreen');
  });
});
