import React from 'react';
import SettingsRow from '../../src/components/ui/SettingsRow';
import SettingSwitch from '../../src/components/ui/SettingSwitch';
import { MaterialIcons } from '@expo/vector-icons';
import { theme } from '../../src/theme';

/**
 * The SettingsRow component is a pure functional component that returns a React element.
 * These tests inspect the returned element tree without needing a full rendering library.
 */
describe('SettingsRow component (UI contract)', () => {
  test('renders an App lock row with a switch and no chevron', () => {
    const onSwitchChange = jest.fn();
    const rowElement = SettingsRow({
      label: 'App lock',
      testID: 'settings-row-app-lock',
      showSwitch: true,
      switchValue: false,
      onSwitchChange,
      showChevron: false,
    });

    // The top‑level element should be a Paper List.Item (type checking is optional)
    expect(rowElement).toBeTruthy();
    expect(rowElement.props.title).toBe('App lock');
    expect(rowElement.props.testID).toBe('settings-row-app-lock');

    // When a switch is requested, the `right` prop should be a function that returns a SettingSwitch
    expect(typeof rowElement.props.right).toBe('function');
    const rightComponent = rowElement.props.right({});
    expect(rightComponent.type).toBe(SettingSwitch);
    expect(rightComponent.props.value).toBe(false);
    expect(rightComponent.props.onValueChange).toBe(onSwitchChange);
  });

  test('renders navigation rows with a chevron icon', () => {
    const onPress = jest.fn();
    const rowElement = SettingsRow({
      label: 'Tax settings',
      testID: 'settings-row-tax-settings',
      onPress,
      showChevron: true,
    });

    expect(rowElement.props.title).toBe('Tax settings');
    expect(rowElement.props.testID).toBe('settings-row-tax-settings');

    // The chevron is provided via the `right` prop
    expect(typeof rowElement.props.right).toBe('function');
    const rightComponent = rowElement.props.right({});
    expect(rightComponent.type).toBe(MaterialIcons);
    expect(rightComponent.props.name).toBe('chevron-right');
    expect(rightComponent.props.size).toBe(24); // typical size; not required but useful check
    expect(rightComponent.props.color).toBeUndefined(); // colour is handled by theme

    // Press handler should be attached
    expect(typeof rowElement.props.onPress).toBe('function');
    rowElement.props.onPress();
    expect(onPress).toHaveBeenCalledTimes(1);
  });

  test('renders Delete all data row styled with error colour and no chevron', () => {
    const onPress = jest.fn();
    const rowElement = SettingsRow({
      label: 'Delete all data',
      testID: 'settings-row-delete-all-data',
      onPress,
      error: true,
      showChevron: false,
    });

    expect(rowElement.props.title).toBe('Delete all data');
    expect(rowElement.props.testID).toBe('settings-row-delete-all-data');

    // Error rows use the error colour from the theme via titleStyle
    const titleStyle = rowElement.props.titleStyle || {};
    expect(titleStyle.color).toBe(theme.colors.error);

    // No chevron should be rendered
    if (rowElement.props.right) {
      const rightComponent = rowElement.props.right({});
      expect(rightComponent.type).not.toBe(MaterialIcons);
    }

    // Press handler works
    expect(typeof rowElement.props.onPress).toBe('function');
    rowElement.props.onPress();
    expect(onPress).toHaveBeenCalledTimes(1);
  });
});
```

