import React from 'react';
import { render, fireEvent, within } from '@testing-library/react-native';
import SettingsRow from '../../src/components/ui/SettingsRow';
import { MaterialIcons } from '@expo/vector-icons';
import { theme } from '../../src/theme';

describe('SettingsRow component', () => {
  test('renders a row with a trailing switch and no chevron', () => {
    const onSwitchChange = jest.fn();

    const { getByTestId, getByText } = render(
      <SettingsRow
        label="App lock"
        testID="settings-row-app-lock"
        showSwitch
        switchValue={false}
        onSwitchChange={onSwitchChange}
        showChevron={false}
      />
    );

    // root element should be reachable via testID
    const row = getByTestId('settings-row-app-lock');
    expect(row).toBeTruthy();

    // label text must be present
    const label = getByText('App lock');
    expect(label).toBeTruthy();

    // a switch (accessibilityRole="switch") should be rendered
    const switchElement = within(row).getByRole('switch');
    expect(switchElement).toBeTruthy();

    // simulate toggling the switch
    fireEvent.press(switchElement);
    expect(onSwitchChange).toHaveBeenCalledTimes(1);
  });

  test('renders a navigation row with a trailing chevron icon', () => {
    const onPress = jest.fn();

    const { getByTestId, getByText } = render(
      <SettingsRow
        label="Tax settings"
        testID="settings-row-tax-settings"
        onPress={onPress}
        showChevron
      />
    );

    const row = getByTestId('settings-row-tax-settings');
    expect(row).toBeTruthy();

    const label = getByText('Tax settings');
    expect(label).toBeTruthy();

    // chevron icon should be rendered using MaterialIcons with name "chevron-right"
    const chevron = within(row).UNSAFE_getByType(MaterialIcons);
    expect(chevron).toBeTruthy();
    expect(chevron.props.name).toBe('chevron-right');

    // pressing the row should call the supplied handler
    fireEvent.press(row);
    expect(onPress).toHaveBeenCalledTimes(1);
  });

  test('renders an error‑styled row without chevron or switch', () => {
    const onPress = jest.fn();

    const { getByTestId, getByText } = render(
      <SettingsRow
        label="Delete all data"
        testID="settings-row-delete-all-data"
        onPress={onPress}
        error
        showChevron={false}
      />
    );

    const row = getByTestId('settings-row-delete-all-data');
    expect(row).toBeTruthy();

    const label = getByText('Delete all data');
    expect(label).toBeTruthy();

    // label should be styled with the error colour from the theme
    const labelStyle = label.props.style;
    const flattened = Array.isArray(labelStyle) ? Object.assign({}, ...labelStyle) : labelStyle;
    expect(flattened?.color).toBe(theme.colors.error);

    // no chevron should be present
    const chevron = within(row).UNSAFE_queryByType(MaterialIcons);
    expect(chevron).toBeNull();

    // no switch should be present
    const maybeSwitch = within(row).queryByRole('switch');
    expect(maybeSwitch).toBeNull();

    // pressing the row triggers onPress
    fireEvent.press(row);
    expect(onPress).toHaveBeenCalledTimes(1);
  });
});
